@article{Wang_Juola_Riddell_2026,
  title={Reproduction and Replication of an Adversarial Stylometry Experiment},
  volume={2},
  url={https://ejournals.uni-muenster.de/replicationresearch/article/view/9414},
  DOI={10.17879/replicationresearch-2026-9414},
  abstractNote={&amp;lt;div id=&amp;quot;abstract1&amp;quot; class=&amp;quot;ltx_abstract&amp;quot;&amp;gt;
&amp;lt;p class=&amp;quot;ltx_p&amp;quot;&amp;gt;&amp;lt;span style=&amp;quot;font-weight: 400;&amp;quot;&amp;gt;Maintaining anonymity in natural language communication remains a challenging task. Even when the number of candidate authors is large, standard authorship attribution techniques that analyze writing style predict the original author with uncomfortably high accuracy. Adversarial stylometry provides a defense against authorship attribution, helping users avoid unwanted deanonymization. This paper reproduces and replicates experiments from a seminal study of defenses against authorship attribution (Brennan et al., 2012). After reproducing the experiment using the original data, we then replicate the experiment by repeating the online field experiment using the procedures described in the original paper. Although we reach the same conclusion as the original paper, our results suggest that the defenses studied may be overstated in their effectiveness. This is largely due to the absence of a control group in the original study. In our replication, we find evidence suggesting that an entirely automatic method, round-trip translation, warrants re-examination because it appears to reduce the effectiveness of established authorship attribution methods.&amp;lt;/span&amp;gt;&amp;lt;/p&amp;gt;
&amp;lt;/div&amp;gt;},
  journal={Replication Research},
  author={Wang, Haining and Juola, Patrick and Riddell, Allen},
  year={2026},
  month={Aug.}
}
